["鬼斧屠戮"] = {"以龙角为主材的绝世神兵，寒芒曾现苍月，即使由寻常兵卒掌握亦能激发不世霸气，听说<font color='#00FF00'>沙巴克武器店</font>隐藏着它的秘密....",149},
["聚灵法杖"] = {"这件青色法杖犹如一股神秘力量在内流动能够释放出无穷的魔力让法师的威力无可匹敌听说<font color='#00FF00'>沙巴克武器店</font>隐藏着它的秘密",149},
["毒龙刺"] = {"剑身锋利如狂风，每一次挥舞都能带来惊人的威力，引领着道士行走江湖，听说<font color='#00FF00'>沙巴克武器店</font>隐藏着它的秘密....",149},
["圣龙战甲"]={"一身龙鳞铸就的银甲,浑身散发着凛冽的气息,威武不凡,令人敬畏",149,"战士职业S3系列",250},
