["猎魔人★勋章(传说)"]={"此勋章是玛法大陆中最为崇高的荣誉象征，只有战功赫赫的玩家才能拥有它，凝聚着千万玩家的信仰和荣耀",249},
["猎魔人★勋章"]={"它如同一面闪烁着神秘光芒的荣耀标志，象征着勇气力量，智慧和毅力拥有它的人就是玛法大陆中真正的猎手",249},
["猎魔人★斗笠"]={"黑色魔法之力凝聚神秘而又威严承载着猎魔人的决心与力量，无论面对何种丧心病狂的怪物，都能令其闻风丧胆",249},
["猎魔人★斗笠(传说)"]={"此斗笠是玛法大陆中最为崇高的荣誉象征，只有战功赫赫的玩家才能拥有它，凝聚着千万玩家的信仰和荣耀",249},
["游龙ぬ锥心斩"]={"这把武器剑芒如游龙出海，每一次斩击都仿佛能撕裂敌人的防御直插敌心,展现出战士强悍的战斗力",249},
["咆哮ぬ怒吼杖"]={"这柄法杖恍若一条神龙,凝聚着无上魔法,每一次挥舞都能引起恐怖的魔法波动,摧毁敌人的防御",249},
["契约ぬ神罚剑"]={"凝聚玄妙道法的神器,锋利无比所过之处无不颤抖,无数敌人在其锋芒下灰飞烟灭,更是威不可挡",249},
["游龙ぬ锥心甲"]={"这件战甲强悍无比,穿上后不仅能够增加战士的攻击力和防御力,更能令敌人在面对战士时心生畏惧",249,"战士职业S6系列",253},
["游龙ぬ锥心袍"]={"这件战袍强悍无比,穿上后不仅能够增加战士的攻击力和防御力,更能令敌人在面对战士时心生畏惧",249,"战士职业S6系列",253},
["咆哮ぬ怒吼甲"]={"它所蕴含的魔法力和防御,足以让任何敌人颤抖,犹如一头狂暴的巨兽在咆哮,每一次施法都似乎要撕裂整片大陆",249,"法师职业S6系列",253},
["咆哮ぬ怒吼袍"]={"它所蕴含的魔法力和防御,足以让任何敌人颤抖,犹如一头狂暴的巨兽在咆哮,每一次施法都似乎要撕裂整片大陆",249,"法师职业S6系列",253},
["契约ぬ神罚甲"]={"契约神罚甲神圣之光护体，道法无尽道士凌空一指，天地为之变色唯有此甲才能抵御魔王侵蚀可镇压天下群魔",249,"道士职业S6系列",253},
["契约ぬ神罚袍"]={"契约神罚袍神圣之光护体，道法无尽道士凌空一指，天地为之变色唯有此甲才能抵御魔王侵蚀可镇压天下群魔",249,"道士职业S6系列",253},
["游龙ぬ锥心盔"]={"铸就巅峰战士的套装,它散发着逆天的威能,凝聚着战士的勇气和决心,只有那些勇敢无畏，永不言败的战士才能佩戴它",249,"战士职业S6系列",253},
["咆哮ぬ怒吼盔"]={"蕴含着法师的狂傲与霸气,施法时就如巨龙咆哮，让人心生敬畏,是法师界中最为神秘强大的套装",249,"法师职业S6系列",253},
["契约ぬ神罚盔"]={"此套装备其上蕴含着天地灵气,拥有着毁天灭地的威力,只要戴上神罚即刻降临，让敌人无所遁形,只能任凭其神圣之力洗礼",249,"道士职业S6系列",253},
["游龙ぬ锥心链"]={"铸就巅峰战士的套装,它散发着逆天的威能,凝聚着战士的勇气和决心,只有那些勇敢无畏，永不言败的战士才能佩戴它",249,"战士职业S6系列",253},
