["猎魔人★勋章(神话)"]={"拥有它的玩家,不仅在战斗中具备强大的能力,更能展现出无与伦比的王者风范,成为玛法大陆中最耀眼的存在",249},
["猎魔人★斗笠(神话)"]={"拥有它的玩家,不仅在战斗中具备强大的能力,更能展现出无与伦比的王者风范,成为玛法大陆中最耀眼的存在!",249},
["阿修罗ぬ命运之殇"]={"唯有愤怒，才能呼唤它的降临,钢铁般的坚韧与血腥般的暴戾,瞬间能展现其犀利的攻击,持剑者从此独步天下",249},
["帝释天ぬ流星之陨"]={"唯此神杖能引领天下风华，蕴含了宇宙的力量和法师的智慧，能够在一瞬间释放出超乎想象的毁灭性能量,让敌人彻底崩溃",249},
["迦楼罗ぬ万剑归宗"]={"此剑其锋利足以撕裂天际之云,其威力足以镇压魔物之心,传承天地之灵气,参悟无上道法，为拥有者带来一份无上的霸气",249},
["阿修罗ぬ神甲"]={"穿上此甲犹如天上降临的战神,剑指敌阵铁蹄踏破战场,神威盖世战意燃烧如火,誓要歼灭敌人驱散黑暗铸就传奇",249,"战士职业S7系列",253},
["阿修罗ぬ神袍"]={"穿上此甲犹如天上降临的战神,剑指敌阵铁蹄踏破战场,神威盖世战意燃烧如火,誓要歼灭敌人驱散黑暗铸就传奇",249,"战士职业S7系列",253},
["帝释天ぬ神甲"]={"身披帝释天神甲犹如神明降下凡间,无坚不摧,任何敢于挑战他的人,最终都将在那闪耀着神光的铠甲下败北",249,"法师职业S7系列",253},
["帝释天ぬ神袍"]={"身披帝释天神袍犹如神明降下凡间,无坚不摧,任何敢于挑战他的人,最终都将在那闪耀着神光的铠甲下败北",249,"法师职业S7系列",253},
["迦楼罗ぬ神甲"]={"穿戴者拥有无坚不摧的防御力和强大的道术力,令人惊叹的是它的美丽与霸气并存,彰显着道士的威严和尊贵",249,"道士职业S7系列",253},
["迦楼罗ぬ神袍"]={"穿戴者拥有无坚不摧的防御力和强大的道术力,令人惊叹的是它的美丽与霸气并存,彰显着道士的威严和尊贵",249,"道士职业S7系列",253},
["阿修罗ぬ神盔"]={"熔炼魔族战魂而成的神装,象征着战士的最高荣耀,就像阿修罗族一样,易怒好斗但骁勇善战，令人勇往直前,无所畏惧",249,"战士职业S7系列",253},
["帝释天ぬ神盔"]={"法师的巅峰套装产自雷云之海的神器，铸成之时群龙乱舞天雷响彻苍穹，此神器装备时亦有雷声轰呜偶尔还可听见龙吟低吼",249,"法师职业S7系列",253},
["迦楼罗ぬ神盔"]={"迦楼罗是传说中的神鸟以龙为食常被形容为有着火红的羽毛和龙头蛇尾的外形其骸骨打造成为最顶级的道士装备",249,"道士职业S7系列",253},
["阿修罗ぬ神链"]={"熔炼魔族战魂而成的神装,象征着战士的最高荣耀,就像阿修罗族一样,易怒好斗但骁勇善战，令人勇往直前,无所畏惧",249,"战士职业S7系列",253},
