["500点声望卷"]={"<font color='#EEC591'>通过击杀各大地图怪物获得</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击后可获得声望点可在<br>盟重省NPC<font color='#00FF00'>斗勋锻造</font>处了<br>解它的用途",161},
["1000点声望卷"]={"<font color='#EEC591'>通过击杀各大地图怪物获得</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击后可获得声望点可在<br>盟重省NPC<font color='#00FF00'>斗勋锻造</font>处了<br>解它的用途",161},
["药品捆绳"]={"<font color='#EEC591'>产自赤月峡谷的捆绳</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击使用后可对<font color='#00FF00'>万年雪<br>霜</font>以及<font color='#00FF00'>疗伤药</font>进行打捆",161},
["经验宝典"]={"<font color='#EEC591'>可在土城药店老板处获得</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击使用后可获得<font color='#00FF00'>1.5倍</font>打<br>怪经验,持续时间60分钟<br>时间可以累计叠加 死亡小<br>退不消失",161},
["双倍经验卷"]={"<font color='#EEC591'>它是玛法勇士最喜爱的宝典</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击使用后可获得<font color='#00FF00'>2倍</font>打<br>怪经验，持续时间60分钟",161},
["九穗禾"]={"<font color='#EEC591'>生长在蛮荒遗迹的禾苗</font><br><font color='#00BFFF'>[材料用途]：</font><br>可交于盟重省酒馆的<font color='#00FF00'>\"酒<br>剑仙\"</font>是获得剑仙传承的<br>必备材料",161},
["怀梦草"]={"<font color='#EEC591'>生长在蛮荒禁地的仙草</font><br><font color='#00BFFF'>[材料用途]：</font><br>可交于盟重省酒馆的<font color='#00FF00'>\"酒<br>剑仙\"</font>是获得剑仙传承的<br>必备材料",161},
["紫罗兰"]={"<font color='#EEC591'>生长在龙之神域二层的仙花</font><br><font color='#00BFFF'>[材料用途]：</font><br>可交于盟重省酒馆的<font color='#00FF00'>\"酒<br>剑仙\"</font>是获得剑仙传承的<br>必备材料",161},
["幽冥花"]={"<font color='#EEC591'>生长在铁血魔窟的奇异花朵</font><br><font color='#00BFFF'>[材料用途]：</font><br>可交于盟重省酒馆的<font color='#00FF00'>\"酒<br>剑仙\"</font>是获得剑仙传承的<br>必备材料",161},
["不死草"]={"<font color='#EEC591'>生长在堕落深渊二层的仙草</font><br><font color='#00BFFF'>[材料用途]：</font><br>可交于盟重省酒馆的<font color='#00FF00'>\"酒<br>剑仙\"</font>是获得剑仙传承的<br>必备材料",161},
["人参果树"]={"<font color='#EEC591'>生长在桃花谷一层的仙家果树</font><br><font color='#00BFFF'>[材料用途]：</font><br>可交于盟重省酒馆的<font color='#00FF00'>\"酒<br>剑仙\"</font>是获得剑仙传承的<br>必备材料",161},
["护心莲"]={"<font color='#EEC591'>生长于桃花谷底天池的仙莲</font><br><font color='#00BFFF'>[材料用途]：</font><br>可交于盟重省酒馆的<font color='#00FF00'>\"酒<br>剑仙\"</font>是获得剑仙传承的<br>必备材料",161},

["酒剑仙的推荐信"]={"<font color='#EEC591'>蜀山剑派酒剑仙的推荐信</font><br><font color='#00BFFF'>[材料用途]：</font><br>可交于<font color='#00FF00'>酒馆一楼</font>的店小二<br>他可帮你引见酒馆老板娘",161},
["玫瑰花"]={"<font color='#EEC591'>艳丽的玫瑰花朵</font><br><font color='#00BFFF'>[材料用途]：</font><br>交于<font color='#00FF00'>酒馆一楼</font>的老板<br>娘有机会领悟酿酒术",161},
["泉水"]={"<font color='#EEC591'>采集于高级地图泉眼的山泉水</font><br><font color='#00BFFF'>[材料用途]：</font><br>盟重<font color='#00FF00'>酒馆一楼的品酒师</font>对它<br>比较感兴趣是炼制<font color='#FF1493'>\"酒\"</font>的必<br>备材料<font color='#00FF00'>具有高保值性</font>前期切<br>记不可贱卖",161},
["高粱"]={"<font color='#EEC591'>产自玛法大陆农田的农作物</font><br><font color='#00BFFF'>[材料用途]：</font><br>可到盟重<font color='#00FF00'>酒馆一楼的品酒师</font><br>师炼制<font color='#FF1493'>\"高梁酒\"</font>后期酿酒必<br>备材料<font color='#00FF00'>具有高保值</font>前期切记<br>不可贱卖",161},
["虎骨"]={"<font color='#EEC591'>产自玛法大陆农田的农作物</font><br><font color='#00BFFF'>[材料用途]：</font><br>可到盟重<font color='#00FF00'>酒馆一楼的品酒师</font><br>师炼制<font color='#FF1493'>\"虎骨酒\"</font>后期酿酒必<br>备材料<font color='#00FF00'>具有高保值</font>前期切记<br>不可贱卖",161},
["高粱酒"]={"<font color='#EEC591'>用泉水配上高粱酿制而成的酒</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击使用后可增加仙剑酒葫芦<br><font color='#00FF00'>10%</font>的酒气值",161},
["虎骨酒"]={"<font color='#EEC591'>用泉水配上虎骨酿制而成的酒</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击使用后可增加仙剑酒葫芦<br><font color='#00FF00'>25%</font>的酒气值",161},
["金矿石"]={"<font color='#EEC591'>产自上古矿洞的神奇金石</font><br><font color='#00BFFF'>[获取途径]：</font><br>挖矿过程中有概率获得,打<br>怪大量掉落,商铺也可购买<br><font color='#00BFFF'>[材料用途]：</font><br>可在盟重省NPC<font color='#00FF00'>\"仓库保管<br>员\"</font>了解它的用途",161},
["金锭"]={"<font color='#EEC591'>对金矿石千锤百炼得到的产物</font><br><font color='#00BFFF'>[材料用途]：</font><br>可在盟重省NPC<font color='#00FF00'>\"仓库保管员\"<br></font>了解它的用途",161},
["金箔"]={"<font color='#EEC591'>由黄金锤炼而成的金色薄片</font><br><font color='#00BFFF'>[材料用途]：</font><br>可在盟重省NPC<font color='#00FF00'>\"仓库保管员\"<br></font>了解它的用途",161},

["1万经验卷"]={"<font color='#EEC591'>可提升人物等级经验的卷轴</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击使用后可获得<font color='#FF1493'>1万</font>经验值",161},
["12万经验卷"]={"<font color='#EEC591'>可提升人物等级经验的卷轴</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击使用后可获得<font color='#FF1493'>12万</font>经验值<br><font color='#00ff00'>可在头顶按钮拍卖行交易</font>",161},
["50万经验卷"]={"<font color='#EEC591'>可提升人物等级经验的卷轴</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击使用后可获得<font color='#FF1493'>50万</font>经验值<br><font color='#00ff00'>可在头顶按钮拍卖行交易</font>",161},
["沃玛密函"]={"<font color='#00FF00'>沃玛寺庙地图爆出的密函</font><br><font color='#00BFFF'>[材料用途]：</font><br>寻得它,就等于寻到了沃玛族<br>的宝藏,可以交给<font color='#00FF00'>沃玛大殿</font>的<br>信使",161},
["祖玛头像"]={"<font color='#00FF00'>祖玛寺庙地图爆出的头像</font><br><font color='#00BFFF'>[材料用途]：</font><br>守在<font color='#00FF00'>\"祖玛之家\"</font>的祖玛族<br>长老正在等候有缘人帮他<br>寻得本族圣物\"祖玛头像\"",161},

["通关文牒"]={"<font color='#EEC591'>古代通过关戍时的凭证</font><br><font color='#00BFFF'>[材料用途]：</font><br>勇士拿着它去寻找镇守<br>在<font color='#00FF00'>通天之路</font>的守陵武将<br>他可以让你面见秦始皇",161},
["孟婆汤"]={"<font color='#00FF00'>骨魔洞地图爆出的孟婆汤</font><br><font color='#00BFFF'>[材料用途]：</font><br>听说守在<font color='#00FF00'>\"骨魔洞五层\"</font>的<br>孟婆正在苦苦寻找此此汤<br>你可以交给她试试",161},
["牛魔王的推荐信"]={"<font color='#00FF00'>牛魔洞地图爆出的推荐信</font><br><font color='#00BFFF'>[材料用途]：</font><br>你可以交给守望在牛魔寺庙<br>大厅的<font color='#00FF00'>\"铁扇公主\"</font>她能帮你<br>传送至牛魔族的宝库",161},
["九珠连环炮"]={"<font color='#EEC591'>能释放出绚丽多彩的烟花</font><br><font color='#00BFFF'>[材料用途]：</font><br>在<font color='#00FF00'>\"赤月魔穴\"</font>双击后有极<br>大概率传送至烟花迷宫进<br>入到烟花神殿",161},
["魔教信物"]={"<font color='#EEC591'>魔族战败后遗留下的信物</font><br><font color='#00BFFF'>[材料用途]：</font><br>可在魔龙城任何地方双击<br>使用,能召唤出<font color='#00FF00'>\"邪魔统帅\"</font>",161},
["魔龙之血"]={"<font color='#EEC591'>由上古龙脉孕育而成的魔之血</font><br><font color='#00BFFF'>[材料用途]：</font><br>可到比奇城的<font color='#00FF00'>\"比奇皇宫\"</font>找到<br>珍宝馆了解它的用处<font color='#FF1493'>玛法最稀<br>有材料</font>之一",161},
["祝福油"]={"<font color='#EEC591'>这个就不用做过多的介绍了</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击使用后,可以给武器提升幸运<br>的物品,其他妙用你得去<font color='#00FF00'>白日门</font>找<br>NPC呼延剑客他会告诉你",161},
["超级祝福油"]={"<font color='#EEC591'>能给人物带来超级幸运的油</font><br><font color='#00BFFF'>[材料用途]：</font><br>白日门的NPC<font color='#00FF00'>\"呼延剑客\"</font>对<br>它了如指掌,你可以找他试试",161},
["技能神石"]={"<font color='#EEC591'>色如灵石微深红,纹似金星细入肌</font><br><font color='#00BFFF'>[材料用途]：</font><br>封魔谷的<font color='#00FF00'>\"淬炼大师\"</font>了解它的用途",161},
["主宰凭证"]={"<font color='#EEC591'>天界之主留在玛法大陆的凭证</font><br><font color='#00BFFF'>[材料用途]：</font><br>可到<font color='#00FF00'>封魔谷的</font>\"封魔堡\"找到封<br>魔谷主了解它的用处<font color='#FF1493'>玛法最稀<br>有材料</font>之一",161},
["求婚戒指"]={"<font color='#EEC591'>慢慢传奇路,悠悠玛法情</font><br><font color='#00BFFF'>[材料用途]：</font><br>可带上心爱之人,到<font color='#00FF00'>婚缘神殿</font><br>找到红娘帮你完成结婚仪式",161},
["沃玛号角"]={"<font color='#EEC591'>沃玛寺庙教主头顶的巨角</font><br><font color='#00BFFF'>[材料用途]：</font><br>创建行会的必备之物",161},
["蚕丝"]={"<font color='#EEC591'>产自蜈蚣洞巨型蠕虫的丝绒<br>游戏中大量爆出</font><br><font color='#00BFFF'>[材料用途]：</font><br>土城左上角仓库保管员处使用",161},
["金蚕丝"]={"<font color='#EEC591'>产自沃玛神庙盘丝大仙的丝绒<br>游戏中大量爆出</font><br><font color='#00BFFF'>[材料用途]：</font><br>土城左上角仓库保管员处使用",161},
["赏金值"]={"<font color='#EEC591'>通过击杀各大地图怪物获得</font><br><font color='#00BFFF'>[材料用途]：</font><br>盟重土城NPC<font color='#00FF00'>\"赏金猎人\"</font>正<br>在收集它，你可以去找他打<br>听下用途",161},
["修复神水"]={"<font color='#EEC591'>取自天池的神奇灵水</font><br><font color='#00BFFF'>[材料用途]：</font><br>双击后可修复装备的持久",161},
["穿云箭"]={"<font color='#EEC591'>一只穿云箭,千军万马来相见<br>拥有了它,你不在是孤胆英雄</font><br><font color='#00BFFF'>[材料用途]：</font><br>可在地图,<font color='#00FF00'>死亡棺材,沃玛二层<br>石墓六层,封魔殿堂,牛魔六层<br>骨魔洞五层,祖玛七层三,魔龙<br>谷</font>使用。<br>可将行会成员召集至你身边",161},
