function getjipin(itemData,id) --获取极品属性
	local t = itemData.Values
	if t == nil then return 0 end
	for i = 1,#t do
		if t[i].Id == id and t[i].Value ~= 0 then
			return t[i].Value
		end
	end
	return 0
end

function getteshu(itemData,id)
	if itemData.ExAbil and next(itemData.ExAbil) then
		local t = itemData.ExAbil.abil[5].v
		for i = 1,#t do
			if t[i][2] == id then
				return t[i][3]
			end
		end
	end
	return 0
end

function getcuilian(itemData) --获取淬炼值
	if itemData.ExAbil and next(itemData.ExAbil) then
		local t = itemData.ExAbil.abil[6].v
		for i = 1,#t do
			if t[i][2] == 209 then
				return t[i][3]
			end
		end
	end
	return 0
end

local function ParseBaseAtt(att, job)
    local attList = {}
    if not att or att == "" or att == "0" or att == 0 then
        return attList
    end
    local attArray = string.split(att, "|")

    local myJob = job or SL:GetMetaValue("JOB")
    for k,v in pairs(attArray) do
        local attData = string.split(v, "#")
    
        local needJob = tonumber(attData[1])
        local attId = tonumber(attData[2])
        local attValue = tonumber(attData[3])
        if (myJob == 3 or needJob == 3 or needJob == myJob) then
            if attList[attId] then
                attList[attId] = attList[attId] + attValue
            else
                attList[attId] = attValue
            end
        end
    end
    return attList
end

